script.lang:
-- Indicator Type INSERT INTO amp_category_class (amp_cat_cls_id, name, description, key_name, is_multiselect, is_ordered) VALUES ((SELECT nextval('AMP_CATEGORY_CLASS_seq')), 'Indicator Type', 'Type of indicator', 'indicator_type', false, false); INSERT INTO amp_category_value (amp_cat_val_id, value, index, deleted, amp_cat_cls_id) VALUES ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Adaptation', 1, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_type')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Mitigation', 2, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_type'));
-- Indicator Disaggregation INSERT INTO amp_category_class (amp_cat_cls_id, name, description, key_name, is_multiselect, is_ordered) VALUES ((SELECT nextval('AMP_CATEGORY_CLASS_seq')), 'Indicator Disaggregation', 'Disaggregation dimensions for indicators', 'indicator_disaggregation', true, false); INSERT INTO amp_category_value (amp_cat_val_id, value, index, deleted, amp_cat_cls_id) VALUES ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Gender', 1, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Age Group', 2, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Geographical Region/Location', 3, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Socio-economic Status', 4, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Vulnerable Group', 5, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Livelihood Type', 6, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_disaggregation'));
-- Indicator Unit of Measure INSERT INTO amp_category_class (amp_cat_cls_id, name, description, key_name, is_multiselect, is_ordered) VALUES ((SELECT nextval('AMP_CATEGORY_CLASS_seq')), 'Indicator Unit of Measure', 'Unit in which indicator is measured', 'indicator_unit_of_measure', false, false); INSERT INTO amp_category_value (amp_cat_val_id, value, index, deleted, amp_cat_cls_id) VALUES ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), '#', 1, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'hectares', 2, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'percent', 3, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'km', 4, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'liters', 5, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'households', 6, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'individuals', 7, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_unit_of_measure'));
-- Indicator Frequency INSERT INTO amp_category_class (amp_cat_cls_id, name, description, key_name, is_multiselect, is_ordered) VALUES ((SELECT nextval('AMP_CATEGORY_CLASS_seq')), 'Indicator Frequency', 'Reporting frequency for indicator', 'indicator_frequency', false, true); INSERT INTO amp_category_value (amp_cat_val_id, value, index, deleted, amp_cat_cls_id) VALUES ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Monthly', 1, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_frequency')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Quarterly', 2, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_frequency')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Yearly', 3, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_frequency')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Biannual', 4, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_frequency')), ((SELECT nextval('AMP_CATEGORY_VALUE_seq')), 'Ad hoc', 5, false, (SELECT amp_cat_cls_id FROM amp_category_class WHERE key_name = 'indicator_frequency'));
